  d.style.left = p.x + "px"; d.style.top = p.y + "px";
  if (g === "vein") d.innerHTML = `<svg viewBox="0 0 40 40"><g stroke="#e0364f" stroke-width="4.5" fill="none" stroke-linecap="round"><path d="M16 4 Q17 15 5 16"/><path d="M24 4 Q23 15 35 16"/><path d="M16 36 Q17 25 5 24"/><path d="M24 36 Q23 25 35 24"/></g></svg>`;
